    int maxSatisfied(vector<int>& customers, vector<int>& grumpy, int minutes) {
        int baseline = 0, n = customers.size();
        for (int i = 0; i < n; ++i) {
            if (grumpy[i] == 0) baseline += customers[i];
        }

        int extra = 0, cur = 0;
        for (int i = 0; i < n; ++i) {
            if (grumpy[i] == 1) cur += customers[i];
